using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    cin >> n >> m;

    if (n <= m) {
        cout << n;
        return 0;
    }

    long long target = n - m;
    long long low = 1, high = 1;

    auto triangular = [](long long x) -> __int128 {
        return static_cast<__int128>(x) * (x + 1) / 2;
    };

    while (triangular(high) < target) {
        high *= 2;
    }

    while (low < high) {
        long long mid = low + (high - low) / 2;
        if (triangular(mid) >= target)
            high = mid;
        else
            low = mid + 1;
    }

    cout << m + low;
    return 0;
}

